from pptx import Presentation
from pathlib import Path
for fname in [r'assets/ppt_pack/ca327de5_20260305大组会-颜雍颀-v5_最终交付.pptx', r'assets/ppt_pack/1c8b74da_literature_report_FINAL_v2-1.pptx']:
    prs=Presentation(fname)
    print('\nFILE:', Path(fname).name, 'slides=', len(prs.slides))
    for i,slide in enumerate(prs.slides,1):
        texts=[]
        for shape in slide.shapes:
            if hasattr(shape,'text'):
                t=' '.join(shape.text.split())
                if t:
                    texts.append(t)
        joined=' | '.join(texts[:8])
        print(f'{i:02d}: {joined[:220]}')

